.darma-loader-darma-b17-frog-leap { --accent: var(--loader-color, #16a34a); --accent-2: var(--loader-secondary-color, #4ade80); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .52); position: relative; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__pad { position: absolute; bottom: 6%; width: 26%; height: 18%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 55%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 40%, transparent); }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__pad:nth-of-type(1) { left: 2%; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__pad:nth-of-type(2) { left: 37%; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__pad:nth-of-type(3) { left: 72%; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__frog { position: absolute; left: 7%; bottom: 14%; width: 16%; height: 30%; border-radius: 46% 46% 40% 40%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent)); animation: darma-loader-darma-b17-frog-leap-frog-hop calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.4, 0, .5, 1) infinite; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__eye { position: absolute; top: -14%; width: 34%; height: 34%; border-radius: 50%; background: var(--accent-2); box-shadow: inset 0 -2px 0 color-mix(in srgb, #000 20%, transparent); }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__eye::after { content: ''; position: absolute; left: 26%; top: 30%; width: 40%; height: 40%; border-radius: 50%; background: #0f172a; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__eye:nth-of-type(1) { left: 8%; }
.darma-loader-darma-b17-frog-leap .darma-loader-darma-b17-frog-leap__eye:nth-of-type(2) { right: 8%; }
@keyframes darma-loader-darma-b17-frog-leap-frog-hop { 0%, 10% { transform: translate(0, 0) scaleY(1); } 16% { transform: translate(0, 8%) scaleY(.78); } 30% { transform: translate(110%, -120%) scaleY(1.12); } 42%, 52% { transform: translate(219%, 0) scaleY(1); } 58% { transform: translate(219%, 8%) scaleY(.78); } 72% { transform: translate(329%, -120%) scaleY(1.12); } 84%, 94% { transform: translate(438%, 0) scaleY(1); } 100% { transform: translate(0, 0) scaleY(1); } }

